# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLE TÜRLERİ 1: YÜKLEMİN TÜRÜNE GÖRE CÜMLELER (T.8.4.19)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Fiil (Eylem) Cümlesi</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Yüklemi çekimli bir FİİL olan cümlelerdir.</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">• Yüklem iş, oluş veya hareket bildirir; kök veya</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" fill="#1e3a8a">gövdesi \'-mak / -mek\' mastar ekini alabilir.</text>\n  <text x="180" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Örnekler:</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" fill="#1e3a8a">• Dedem bize Ergenekon Destanı\'nı anlattı. (anlat-)</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kültürümüzü gelecek kuşaklara aktarmalıyız.</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">• Olumsuzu \'-ma / -me\' ekiyle yapılır.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İsim (Ad) Cümlesi</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Yüklemi ek fiil (-idi, -imiş, -ise, -dir) almış</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#14532d">bir İSİM, SIFAT, ZAMİR, EDAT veya FİİLİMSİ olan</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#14532d">cümlelerdir (\'var, yok, değil\' dahil).</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Örnekler:</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" fill="#14532d">• Türkülerimiz milletimizin ortak hafızasıdır.</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#14532d">• En büyük amacımız vatanı korumaktır. (Fiilimsi!)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">• Olumsuzu \'değil\' veya \'yok\' ile yapılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLE TÜRLERİ 2: YÜKLEMİN YERİNE (ÖGE DİZİLİŞİNE) GÖRE CÜMLELER</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Kurallı (Düz) Cümle</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Yüklem SONDADIR.</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#164e63">• Türkçenin temel söz</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#164e63">dizimine uygun cümledir.</text>\n  <text x="125" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Örnek:</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" fill="#164e63">\'Misafirperverlik Anadolu</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" fill="#164e63">insanının en güzel</text>\n  <text x="125" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">geleneğidir.\' (Sonda)</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Devrik (Kuralsız) Cümle</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Yüklem BAŞTA veya ORTADADIR.</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#713f12">• Şiirde, atasözlerinde ve</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#713f12">samimi anlatımda sık görülür.</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Örnek:</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#713f12">\'Yeşerir bozkırın ortasında</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#713f12">asvırlık çınarlar.\'</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">(Yüklem: Yeşerir - Başta)</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">3. Eksiltili Cümle</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Yüklemi SÖYLENMEMİŞTİR (...)</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#881337">• Yüklem okuyucunun hayal</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#881337">gücüne bırakılır; sonuna (...)</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#881337">üç nokta konur.</text>\n  <text x="575" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Örnek:</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#881337">\'Karşıda karlı dağlar, şırıl</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">şırıl akan dereler...\'</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ANLAMLARINA GÖRE CÜMLELER VE ANLATIM BOZUKLUKLARINA GİRİŞ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Anlamlarına Göre Cümleler</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#581c87">• Olumlu Cümle: Yargı gerçekleşir (\'Geldi, güzeldir\').</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#581c87">• Olumsuz Cümle: Yargı gerçekleşmez (-ma/-me, -siz, yok, değil).</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Biçimce ve Anlamca Olumluluk/Olumsuzluk:</text>\n  <text x="180" y="158" text-anchor="middle" font-size="11" fill="#581c87">• \'Seni anlamıyor değilim.\' → Biçimce olumsuz,</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">anlamca OLUMLU (Anlıyorum).</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#581c87">• \'Ne aradı ne sordu.\' → Biçimce olumlu,</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">anlamca OLUMSUZ (Aramadı, sormadı).</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Anlatım Bozukluklarına Giriş (Anlamsal)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">1. Gereksiz Sözcük: \'Sağlıklı ve sıhhatli\' (biri fazla)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#14532d">2. Anlamca Çelişen: \'Elbette gelmiş olabilir\' (kesinlik+ihtimal)</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#14532d">3. Sözcüğün Yanlış Anlamda Kullanımı: \'Fiyatlar çok</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#14532d">pahalı\' (fiyat yüksek/düşük, ürün pahalı/ucuz olur)</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#14532d">4. Sözcüğün Yanlış Yerde Kullanımı: \'Yeni durağa</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#14532d">geldim\' yerine \'Durağa yeni geldim\'.</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">5. Deyim Yanlışı ve Anlam Belirsizliği</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
